// Class 12 English - Vistas Chapter 4: The Enemy (Pearl S. Buck)
// Fully standardized to English Core Blueprint & AGENTS.md guidelines
// Theme Color: #D50000

export const c12EngV4HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(213, 0, 0, 0.22), rgba(183, 28, 28, 0.1)); border: 1.5px solid #D50000; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(213, 0, 0, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #D50000; color: #FFF; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">VISTAS &bull; CHAPTER 4</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE (SUPPLEMENTARY READER)</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">The Enemy</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Pearl S. Buck (1892&ndash;1973, Nobel Laureate) &mdash; Medical Ethics, Human Compassion &amp; Transcending Wartime Hatred\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(213, 0, 0, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #D50000; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: The Enemy\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #D50000;\">Author:</b> Pearl S. Buck (Nobel Prize in Literature 1938 &amp; Pulitzer Prize)</div>\n      <div><b style=\"color: #D50000;\">Genre:</b> Moral Wartime Drama / Psychological Realism</div>\n      <div><b style=\"color: #D50000;\">Setting:</b> Coastal Japan, World War II (Pacific Theatre)</div>\n      <div><b style=\"color: #D50000;\">Protagonist:</b> Dr. Sadao Hoki (Eminent Japanese Surgeon &amp; Scientist)</div>\n      <div><b style=\"color: #D50000;\">Key Figures:</b> Hana (Devoted Wife), Tom (American POW), General Takima (Commander)</div>\n      <div><b style=\"color: #D50000;\">The Conflict:</b> Hippocratic Oath &amp; Universal Humanity vs. Narrow National Loyalty</div>\n      <div><b style=\"color: #D50000;\">The Escape Route:</b> An uninhabited island via fishing boat to Korean vessels</div>\n      <div><b style=\"color: #D50000;\">Philosophical Question:</b> <i>\"I wonder why I could not kill him?\"</i></div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Context -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Moral Framework\n  </h2>\n  <p>\n    <b style=\"color: #D50000;\">'The Enemy'</b>, crafted by Nobel Laureate <b style=\"color: #D50000;\">Pearl S. Buck</b>, is a gripping moral drama set on the rocky shores of Japan during the height of World War II. Celebrated for her deep cross-cultural understanding and profound humanitarian vision, Buck explores the agonizing ethical dilemma faced by an individual when professional duty, human compassion, and patriotic allegiance come into direct, irreconcilable conflict.\n  </p>\n  <p>\n    The narrative revolves around <b style=\"color: #D50000;\">Dr. Sadao Hoki</b>, a distinguished Japanese surgeon and medical researcher who discovers an escaped American prisoner of war bleeding to death on the beach outside his ancestral coastal home. As a patriotic subject of imperial Japan during total war, harboring an enemy combatant constitutes treason punishable by summary execution. Yet, as a dedicated physician bound by the sacred Hippocratic oath, abandoning a dying patient violates the highest laws of humanity. Navigating the suspicion of his nationalist servants, the volatile health of the egocentric military commander <b style=\"color: #D50000;\">General Takima</b>, and his own ingrained cultural prejudices, Sadao chooses the path of medical integrity, demonstrating that universal human brotherhood transcends geopolitical hostility and wartime propaganda.\n  </p>\n\n  <!-- Section 2: Chronological Narrative Architecture -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    2. Chronological &amp; Thematic Narrative Architecture\n  </h2>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(i) Dr. Sadao's Heritage &amp; Medical Eminence</h3>\n  <p>\n    Dr. Sadao Hoki resided in a square stone house built high on the rocky Japanese coast above a narrow beach sheltered by bent pine trees. His father was a deeply traditional, patriotic Japanese patriarch whose sole ambition was Sadao's education. At twenty-two, Sadao was sent to America to master surgery and medicine, returning at thirty as a distinguished surgeon and scientist who was perfecting a major discovery to render surgical wounds entirely clean.\n  </p>\n  <p>\n    Because of his vital scientific research and because the ailing military commander <b style=\"color: #D50000;\">General Takima</b> might require emergency surgery at any moment, Sadao was exempted from military service abroad with the imperial troops. In America, Sadao met <b style=\"color: #D50000;\">Hana</b> at an American professor's house, but he refrained from falling in love until he ensured she was Japanese by birth, respecting his father's traditional expectations. They returned to Japan, married in ancient Japanese ceremonial style, and lived harmoniously with two children.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(ii) The Wounded American on the Rocks</h3>\n  <p>\n    One misty twilight, while standing on their veranda watching the sea mist crawl up the beach, Sadao and Hana witness a dark shape flung out of the churning ocean onto the jagged coral reef. Rushing down the rocks, they discover a man crawling on his hands and knees before collapsing face down in the sand. Turning him over, they see wet yellow hair, rough stubble, and a battered, youthful Caucasian face: he is an American prisoner of war. A tattered cap bears the faint lettering: <b style=\"color: #D50000;\">'U.S. Navy'</b>.\n  </p>\n  <p>\n    The sailor has been shot in the lower back near his right kidney; the wound has torn open on the sharp coral, oozing dark blood. Instinctively, Sadao's trained surgical fingers pack the bleeding laceration with sea moss to stem the hemorrhage.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(iii) The Agonizing Moral Impasse</h3>\n  <p>\n    A harrowing moral debate ensues between husband and wife. If they shelter the white man, they will be arrested and executed for treason; if they hand him over to the police, he will surely die; if they push him back into the sea, they commit murder. Sadao remarks: <i>\"If the man were whole I could turn him over to the police without thinking... But since he is wounded...\"</i>\n  </p>\n  <p>\n    Unable to commit murder, they carry the unconscious soldier into Sadao's father's traditional bedroom, adorned with fine tatami mats and silk quilts.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(iv) Domestic Revolt &amp; The Servants' Departure</h3>\n  <p>\n    The household servants are horrified by the presence of the American prisoner. The maid, <b style=\"color: #D50000;\">Yumi</b>, fiercely refuses to wash the dirty white soldier, declaring she has never washed an American and never will. Hana washes him herself with warm water. The old gardener and the cook openly criticize their master, arguing that nature intended the man to die&mdash;the gun shot him and the sea reef tore him; if the master heals what gun and sea attempted to kill, retribution will fall upon the household.\n  </p>\n  <p>\n    On the seventh day, the servants pack their belongings and resign in protest, weeping but maintaining patriotic defiance. Hana pays them their full wages with calm dignity.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(v) The Heroic Surgery: Duty Above Hatred</h3>\n  <p>\n    Sadao operates on the prisoner with masterful precision. Hana, unaccustomed to surgical blood, administers the anesthetic (ether) and rushes out to the garden to vomit in distress, but bravely returns to assist her husband. Sadao probes the wound near the kidney with accustomed surgical fingers, cursing the American soldier under his breath as <i>'my friend'</i>&mdash;his habitual term of endearment for patients during surgery. With a delicate stroke of his scalpel, he extracts the bullet. The patient groans in stupor, his weak pulse stabilizes, and his life is saved.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(vi) General Takima's Promise &amp; Three Sleepless Nights</h3>\n  <p>\n    When the prisoner, named <b style=\"color: #D50000;\">Tom</b>, regains consciousness and begins recovering, Sadao knows the situation is unsustainable. A messenger in official uniform arrives at the house, terrifying Hana into thinking Sadao is being arrested. However, the messenger has only come to summon Sadao to the palace because General Takima is in pain.\n  </p>\n  <p>\n    Sadao confides the entire truth about the American soldier to General Takima. The General, understanding and practical, realizes he cannot allow Sadao to be arrested because Sadao is the only surgeon who can keep him alive. The General promises to send his private assassins to Sadao's house at night to kill the American quietly and remove his body.\n  </p>\n  <p>\n    For three consecutive nights, Sadao suffers through restless, agonizing sleeplessness, listening for the sound of footfalls, rustling branches, or a sudden scuffle in the garden. Each morning, however, he finds the American alive, healthy, and cheerful.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(vii) The General's Self-Absorption &amp; Sadao's Master Plan</h3>\n  <p>\n    Realizing the strain is breaking his home and that the General had forgotten his promise due to his own acute illness, Sadao takes destiny into his own hands. He equips a sturdy boat with food, fresh bottled water, extra quilts, and a flashlight.\n  </p>\n  <p>\n    At night, Sadao instructs Tom to row out to a little uninhabited island near the coast. The island is not guarded because in storms it becomes submerged. He tells Tom to wait there until a Korean fishing boat passes by, as Korean boats fish close to the shore. He gives Tom strict signaling instructions: flash the light twice at sunset if he runs out of food, flash it once if he is okay, and never signal in darkness lest the beam be detected. Tom clutches Sadao's hand in overwhelming gratitude and departs into the black ocean.\n  </p>\n\n  <h3 style=\"color: #D50000; font-size: 17px; margin-top: 22px;\">(viii) The Resolution &amp; Concluding Epiphany</h3>\n  <p>\n    A week later, after performing a successful emergency operation on General Takima, Sadao informs the convalescing General that the prisoner has 'escaped'. The General guiltily confesses that he forgot to dispatch his assassins because he was completely preoccupied with his own suffering, pleading with Sadao not to disclose his lapse of duty, assuring him of his royal favor.\n  </p>\n  <p>\n    That evening at sunset, Sadao stands upon his veranda gazing out toward the island. No light flashes&mdash;the American has safely boarded a Korean fishing boat and escaped. Looking across the twilight waters, Sadao remembers all the white faces he had known in America: his dull professor, his talkative landlady who nursed him through influenza despite her prejudice, and his young patient Tom. Sadao wonders in quiet contemplation: <i>\"Strange. I wonder why I could not kill him?\"</i>\n  </p>\n\n  <!-- Section 3: Psychological Character Profiles -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    3. Psychological Character Sketches &amp; Profiles\n  </h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-bottom: 25px;\">\n    \n    <!-- Dr. Sadao Hoki -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 8px 0;\">1. Dr. Sadao Hoki (The Ethical Physician)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A master surgeon and scientist. Dedicated to his homeland, he was raised under strict Japanese traditionalism. When confronted with a dying enemy, his medical conscience and fundamental human decency triumph over political indoctrination. He displays exceptional resourcefulness in saving the soldier's life twice&mdash;first on the operating table and later by orchestrating his midnight escape.\n      </p>\n    </div>\n\n    <!-- Hana -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 8px 0;\">2. Hana (The Compassionate Anchor)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        Sadao's refined, supportive wife. Though terrified of arrest and nauseated by the sight of surgical blood, she washes the wounded soldier herself when the servants mutiny. She administers anesthesia during surgery and manages the household with dignity when the domestic staff abandons them, providing unwavering moral and emotional support to Sadao.\n      </p>\n    </div>\n\n    <!-- General Takima -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 8px 0;\">3. General Takima (The Self-Absorbed Commander)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        An ailing, ruthless military leader who was victorious in Manchuria and notoriously cruel to his wife. Facing severe illness, his self-absorption eclipses his military duties. He protects Sadao from treason charges because he cannot risk losing the only surgeon skilled enough to save his life, demonstrating that selfish survival outweighs wartime zeal.\n      </p>\n    </div>\n\n  </div>\n\n  <!-- Section 4: Literary & Rhetorical Devices Master Table -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    4. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14.5px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(213, 0, 0, 0.25); color: #FFFFFF; border-bottom: 2px solid #D50000;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Literary &amp; Thematic Effect</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #D50000;\">Dramatic Irony</td>\n          <td style=\"padding: 12px 14px;\">Calling the wounded enemy soldier <i>'my friend'</i> during surgery out of professional habit.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Highlights the instinctive, sub-conscious humanity of a surgeon that supersedes conscious wartime enmity.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #D50000;\">Moral Dilemma &amp; Conflict</td>\n          <td style=\"padding: 12px 14px;\">Harboring the enemy soldier vs. Handing him over to military execution.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Pits institutional patriotism against universal human ethics, testing the boundaries of the human conscience.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #D50000;\">Symbolism</td>\n          <td style=\"padding: 12px 14px;\">The sea mist, the sea moss, and the white flashlight beam.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Mist symbolizes moral ambiguity and danger; sea moss symbolizes natural healing; the flashlight symbolizes liberation and safety.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #D50000;\">Situational Irony</td>\n          <td style=\"padding: 12px 14px;\">General Takima, head of the military, shields Sadao and forgets to send assassins due to his own health fears.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Exposes the fragility of military fanaticism when confronted with personal human mortality.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 5: Board Exam Strategy & High-Scoring Tips Box -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border-left: 5px solid #D50000; border-radius: 8px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 18px; margin: 0 0 10px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>🎯</span> Board Examination Master Tips: Scoring 100% in The Enemy\n    </h3>\n    <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px; margin: 0; line-height: 1.8;\">\n      <li><b style=\"color: #D50000;\">Differentiate Roles of Sadao &amp; Hana:</b> Note that Hana washed the prisoner herself with warm water when Yumi refused, and administered ether despite feeling nauseous.</li>\n      <li><b style=\"color: #D50000;\">Explain the Escape Plan:</b> Mention the key elements of the escape: <b style=\"color: #D50000;\">uninhabited island, food, water, flashlight signals, and boarding a Korean fishing boat</b>.</li>\n      <li><b style=\"color: #D50000;\">Incorporate Key Vocabulary:</b> Integrate terms like <b style=\"color: #D50000;\">Hippocratic Oath</b>, <b style=\"color: #D50000;\">humanitarian ethics</b>, <b style=\"color: #D50000;\">patriotic chauvinism</b>, and <b style=\"color: #D50000;\">moral fortitude</b>.</li>\n    </ul>\n  </div>\n\n</div>\n";

export const c12EngV4HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Section Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(213, 0, 0, 0.22), rgba(183, 28, 28, 0.1)); border-left: 5px solid #D50000; padding: 16px 20px; border-radius: 8px; margin-bottom: 25px;\">\n    <h2 style=\"color: #D50000; font-weight: 900; margin: 0 0 4px 0; font-size: 21px;\">\n      BOARD EXAMINATION QUESTIONS &amp; MODEL ANSWERS\n    </h2>\n    <span style=\"color: #94A3B8; font-size: 14px; font-weight: 600;\">Standardized to CBSE &amp; JKBOSE Class XII English Core Blueprint &bull; Theme Color Standardized</span>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 26px 0 16px 0;\">\n    SECTION A: Extract-Based Objective Questions (1 Mark Each)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #D50000;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #D50000;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"The man moaned with pain in his stupor but he did not awaken. 'The best thing that we could do would be to put him back into the sea,' Sadao said, answering himself. Now that the bleeding was stopped for the moment he stood up and dusted the sand from his hands. 'Yes, undoubtedly that would be best,' Hana said steadily. But neither of them moved.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q1: Who was the unconscious man lying wounded on the beach?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> An escaped American prisoner of war and <b style=\"color: #D50000;\">U.S. Navy</b> sailor named Tom.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q2: What action did both Sadao and Hana verbally agree would be safest?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> To throw the wounded white soldier back into the ocean.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q3: What does the sentence 'But neither of them moved' reveal about their inner morality?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Their innate human compassion and physician's conscience prevented them from committing deliberate murder.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q4: What immediate medical treatment had Sadao provided to stop the bleeding?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> He packed the gaping bullet wound with <b style=\"color: #D50000;\">sea moss</b> gathered from the beach.\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #D50000;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #D50000;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"'I have never washed a white man,' she said, 'and I will not wash so dirty a one now.' Hana cried at her severely, 'You will do what your master commands you!' 'There is so much fear in the maid's voice,' Hana thought. 'Is it anything that can be hidden?'\"\n    </p>\n    \n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q5: Who refused to wash the wounded American soldier?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #D50000;\">Yumi</b>, the maid and nursemaid of Sadao's children.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q6: Why did the maid refuse to obey Hana's direct command?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Out of patriotic defiance and fear of being branded a traitor aiding the national enemy.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q7: How did Hana resolve the crisis of cleaning the wounded soldier?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Hana maintained her dignity and thoroughly washed the soldier herself with hot water.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q8: What did the servants do seven days after the soldier was brought into the house?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> All three servants (Yumi, the gardener, and the cook) packed their belongings and resigned in protest.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #D50000;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #D50000;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"He had been forgotten, the General had said! But Sadao knew that it was not merely forgetfulness. The old man was sick and he thought only of himself. 'I care nothing for the man, Excellency,' Sadao said, 'but having operated on him with such success...' 'Yes, yes,' the General said. 'It only makes me feel you more indispensable to me.'\"\n    </p>\n    \n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q9: What had General Takima promised to do regarding the American prisoner?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> To send his private assassins to assassinate the soldier quietly and remove his body.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q10: Why did the General fail to dispatch the assassins as promised?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> He was suffering from severe cardiac pain and was totally absorbed in his own health.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q11: Why did the General consider Dr. Sadao completely indispensable?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Sadao was the only surgeon skilled enough to successfully perform emergency surgery on him.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q12: How did the General's self-absorption inadvertently shield Sadao from arrest?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> The General could not execute or prosecute Sadao without jeopardizing his own medical survival.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #D50000;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #D50000;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"He stood on the veranda looking out at the sea from whence the young man had come that other night. And into his mind, although without reason, there came other white faces he had known... 'Strange,' he thought. 'I wonder why I could not kill him?'\"\n    </p>\n    \n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q13: Where is Dr. Sadao standing at the conclusion of the story?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> On the veranda of his home, looking out across the sea toward the island.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q14: How did Sadao verify that the American soldier had safely escaped?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> No flashlight signal came from the island at sunset, confirming he had boarded a Korean boat.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q15: What memories surface in Sadao's mind at this moment?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Memories of Americans he encountered while studying in the US: his anatomy professor, his landlady, and Tom.\n    </p>\n\n    <p>\n      <b style=\"color: #D50000; font-size: 15px;\">Q16: What profound philosophical question does Sadao contemplate at the end?</b><br/>\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> <i>\"I wonder why I could not kill him?\"</i>&mdash;reflecting the mystery of universal human empathy.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: Why was Dr. Sadao not sent abroad with the Japanese military troops?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Dr. Sadao was retained in Japan for two reasons: first, he was perfecting a major scientific discovery to render surgical wounds entirely clean; second, the elderly <b style=\"color: #D50000;\">General Takima</b> was in poor health and might require emergency surgery at any hour.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: What influence did Sadao's father have on his education and marriage?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Sadao's father was a traditionalist whose sole ambition was Sadao's education, sending him to America at twenty-two. Sadao respected his father so deeply that he waited to fall in love with Hana until confirming she was of pure Japanese lineage, marrying in strict Japanese tradition.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: What initial dilemma did Sadao and Hana confront on discovering the wounded soldier?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> If they sheltered the American POW, they faced arrest and execution for treason; if they handed him to the police, he would certainly die; if they pushed him back into the stormy sea, they committed murder. Their human conscience compelled them to bring him indoors.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: Why did the domestic servants abandon Dr. Sadao's household?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> The servants believed Sadao's actions were unpatriotic and defied natural fate. They felt that saving an enemy soldier who had been shot by a gun and slashed by the sea was an omen that would bring divine wrath upon the house, so they resigned in protest.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: How did Hana assist Dr. Sadao during the emergency surgery?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Hana washed the soldier herself when Yumi refused. During surgery, she held the cotton saturated with anesthetic (<b style=\"color: #D50000;\">ether</b>) to the patient's nostrils. Though she retched and vomited in the garden from the sight of blood, she returned bravely to assist her husband.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: Why did Dr. Sadao address the American soldier as 'my friend' during the operation?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> In the operating theater, Sadao's professional medical subconscious completely superseded his political awareness. Calling patients 'my friend' was an ingrained habit he used to soothe patients during surgery, unconsciously treating the enemy as a fellow human being.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: Why did General Takima promise to send his private assassins?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> General Takima wanted to solve Sadao's dilemma quietly without a public scandal that might lead to Sadao's arrest. By having his private assassins eliminate Tom and dispose of the body, the General sought to protect his indispensable personal surgeon.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: What psychological ordeal did Dr. Sadao endure for three nights?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> For three consecutive nights, Sadao lay awake in agonizing suspense, listening for the footsteps of the General's assassins, rustling garden leaves, or a muffled groan. Each morning, finding the American still alive and cheerful stretched his nerves to breaking point.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: What provisions did Dr. Sadao provide in the boat for Tom's escape?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Sadao placed fresh bottled water, food, and warm quilts in a sturdy boat. He also gave Tom his own flashlight and dressed him in traditional Japanese clothes with a black cloth wrapped around his blond hair to conceal his identity.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: What escape instructions did Sadao give to the American prisoner?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Sadao instructed Tom to row to an uninhabited island near the coast and wait for a Korean fishing boat. He was to flash his light twice at sunset if he ran out of food, flash once if safe, and never signal after dark to avoid detection.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: Why did General Takima plead with Sadao not to disclose his failure to send assassins?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> The General realized that forgetting to eliminate an enemy POW due to personal illness was a dereliction of military duty that could be interpreted as treason. Fearing disgrace, he begged Sadao for secrecy, promising him lifetime protection.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #D50000;\">\n    <h4 style=\"color: #D50000; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: How does the ending of 'The Enemy' highlight the triumph of human empathy?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Despite being raised under rigid nationalism, Sadao successfully saves the American twice and engineers his escape. Looking at the misty sea, his closing question&mdash;<i>\"I wonder why I could not kill him?\"</i>&mdash;celebrates the innate triumph of human brotherhood over hatred.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer / Thematic Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q29: How does Dr. Sadao resolve the conflict between his duty as a doctor and his duty as a patriotic citizen of Japan?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #D50000;\">Model Answer:</b><br/>\n      <b>1. The Dual Imperatives:</b> In Pearl S. Buck's 'The Enemy', Dr. Sadao Hoki faces an agonizing moral dilemma. As a patriotic Japanese subject during World War II, harboring an escaped American sailor constitutes treason. Conversely, as a surgeon bound by the sacred Hippocratic oath, letting a bleeding man die without medical intervention violates the highest moral law.<br/><br/>\n      <b>2. Prioritizing Medical Duty:</b> Sadao resolves this crisis through a sequential hierarchy of ethics. First, he prioritizes the immediate preservation of human life. Overcoming the defiance of his domestic servants and personal danger, he performs delicate surgery, extracts the bullet, and nurses the POW back to health.<br/><br/>\n      <b>3. Fulfilling Civic Duty &amp; Final Resolution:</b> Having honored his medical vows, Sadao attempts to fulfill his civic duty by confessing the truth to General Takima. However, when the General forgets to send his assassins due to illness, Sadao refuses to act as an executioner. He arranges Tom's peaceful escape on a boat. In doing so, Sadao proves that universal human compassion supersedes narrow political nationalism.\n    </p>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q30: Contrast the reaction of the servants with that of Dr. Sadao and Hana towards the wounded American prisoner.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #D50000;\">Model Answer:</b><br/>\n      <b>1. The Servants' Narrow Chauvinism:</b> The domestic servants&mdash;Yumi, the old gardener, and the cook&mdash;represent uneducated, rigid wartime nationalism. Conditioned by propaganda, they view the American strictly as an enemy who deserves death. Yumi adamantly refuses to clean him; the gardener views treating the man as an insult to nature and the gun that shot him. Ultimately, they abandon the family in protest.<br/><br/>\n      <b>2. Sadao and Hana's Broad Humanitarianism:</b> In sharp contrast, Sadao and Hana, educated abroad, possess a broader humanitarian perspective. While acutely aware of the treason charges, they recognize a fellow human being in desperate agony. Hana displays extraordinary resilience by washing the soldier herself and administering anesthesia despite physical nausea.<br/><br/>\n      <b>3. Conclusion:</b> The contrast underscores the central theme of the story: true nobility and moral courage lie not in blind herd nationalism, but in empathy and respect for the sanctity of human life.\n    </p>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q31: Analyze the character of General Takima. How does his self-absorption contrast with Dr. Sadao's selflessness?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #D50000;\">Model Answer:</b><br/>\n      <b>1. Introduction:</b> General Takima represents the decadent military aristocracy of wartime Japan. In Manchuria, he was celebrated as a ruthless commander, yet in his private life, he is tyrannical and physically abusive toward his wife.<br/><br/>\n      <b>2. Egocentric Survival:</b> Faced with a failing heart and chronic suffering, the General's patriotic zeal completely dissolves into selfish survival. When Sadao reports the American prisoner, the General does not react with military outrage; instead, he shields Sadao because Sadao is the only surgeon he trusts to keep him alive. His failure to send the promised assassins stems entirely from his self-absorbed struggle with illness.<br/><br/>\n      <b>3. Contrast with Sadao:</b> While Sadao risks his career, home, and life to preserve a stranger's existence, the General neglects his official duties solely to preserve his own skin. Takima's plea for secrecy seals the moral contrast: Sadao acts out of noble altruism, while the supreme military commander acts out of craven self-interest.\n    </p>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q32: Explain how Hana emerges as a pillar of strength and compassion in 'The Enemy'.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #D50000;\">Model Answer:</b><br/>\n      <b>1. Introduction:</b> While Dr. Sadao executes the technical medical intervention, Hana serves as the emotional and moral backbone of the narrative, embodying quiet resilience, unconditional support, and deep humanity.<br/><br/>\n      <b>2. Facing Domestic Crisis:</b> When the servants rebel, Hana avoids hysteria. Instead of pleading with Yumi, she takes hot water and washes the dirty, wounded enemy soldier herself with tender care. In the operating room, although unaccustomed to surgical gore and vomiting outside from distress, she masters her fear and administers the anesthetic, following Sadao's instructions precisely.<br/><br/>\n      <b>3. Sustaining Dignity:</b> When the servants resign, Hana pays their wages with serene dignity, refusing to display distress. She bears the psychological dread of the messenger's arrival and the sleepless nights of waiting. Her steadfast composure enables Sadao to perform his duties and successfully orchestrate Tom's escape.\n    </p>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q33: How does Pearl S. Buck portray racial prejudice on both sides of the Pacific conflict in 'The Enemy'?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #D50000;\">Model Answer:</b><br/>\n      <b>1. Two-Way Racial Prejudice:</b> Pearl S. Buck presents racial prejudice not as a unilateral flaw, but as a reciprocal human failing poisoning both American and Japanese societies during wartime.<br/><br/>\n      <b>2. Sadao's Experience in America:</b> Sadao remembers the subtle contempt he endured as a Japanese student in the United States. His anatomy professor was dull, his classmates aloof, and his white landlady rented him a room only with great reluctance, treating him with condescension even while nursing him during influenza.<br/><br/>\n      <b>3. Japanese Hostility:</b> In Japan, racial chauvinism is equally intense. The servants view all white people as inherently evil, while Sadao's father refused to allow any foreign object into his traditional room. Even Sadao initially feels instinctive revulsion toward Tom's white skin and yellow hair. Yet, by breaking through these artificial barriers to save a life, Buck proves that beneath racial conditioning beats a shared human heart.\n    </p>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(213, 0, 0, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #D50000; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q34: What is the significance of the final line of the story: 'Strange, I wonder why I could not kill him?'\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #D50000;\">Model Answer:</b><br/>\n      <b>1. Concluding Introspection:</b> Standing upon his veranda under the twilight sky, watching the silent horizon where Tom has safely escaped, Dr. Sadao reflects on his actions with quiet wonder.<br/><br/>\n      <b>2. The Conflict of Identity:</b> Rationally, Sadao was trained to consider Americans as enemies of his nation. He harbored memories of American racial prejudice and knew that helping Tom risked everything he held dear. Logically, he had every reason to allow the wounded soldier to drown or let the assassins eliminate him.<br/><br/>\n      <b>3. The Triumph of Universal Brotherhood:</b> His question&mdash;<i>\"Strange, I wonder why I could not kill him?\"</i>&mdash;encapsulates the sublime mystery of human conscience. When faced with a suffering individual, the sacred physician's instinct and primal empathy rendered murder impossible. It affirms that universal human brotherhood is deeper and more permanent than any temporary political warfare.\n    </p>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #D50000; font-size: 20px; font-weight: 800; border-bottom: 2px solid #D50000; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Reading With Insight)\n  </h2>\n\n  <!-- NCERT Q1 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #D50000; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #D50000; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q35 (NCERT 1): There are moments in life when we have to make hard choices between our roles as private individuals and as citizens with a sense of national loyalty. Discuss with reference to 'The Enemy'.</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> In 'The Enemy', Dr. Sadao confronts this agonizing conflict when an American prisoner of war washes ashore at his home. As a patriotic citizen, his national duty demanded handing the enemy combatant over to the military police for execution. However, as a physician bound by medical ethics, his duty was to save a dying human life. Sadao prioritizes his universal human duty first by performing life-saving surgery, and subsequently safeguards his national allegiance by reporting the matter to General Takima, ultimately resolving the crisis with compassionate resourcefulness by orchestrating the prisoner's escape.\n    </p>\n  </div>\n\n  <!-- NCERT Q2 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #D50000; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #D50000; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q36 (NCERT 2): Dr Sadao was compelled by his duty as a doctor to help the enemy soldier. What made Hana, his wife, sympathetic to him in the face of open defiance from the domestic staff?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Hana was motivated by natural human empathy, feminine compassion, and profound marital loyalty to Sadao. Although she was terrified of treason charges and revolted by the sight of surgical blood, she recognized that throwing a helpless, bleeding man back into the sea was cold-blooded murder. When the servants mutinied out of superstitious prejudice, Hana's innate sense of dignity and human kindness led her to wash the soldier herself and administer anesthesia during the surgery.\n    </p>\n  </div>\n\n  <!-- NCERT Q3 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #D50000; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #D50000; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q37 (NCERT 3): How would you explain the reluctance of the soldier to leave the shelter of the doctor's home even when he knew he couldn't stay there without risk to the doctor and himself?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> Tom's reluctance stemmed from overwhelming gratitude and psychological security. In Sadao and Hana's home, the battered American youth had experienced miraculous medical care and gentle compassion from people he had been taught were his mortal enemies. Outside, he faced certain torture and execution by the Japanese military. Knowing how rare such kindness was during wartime, Tom remarked that if all Japanese were like Sadao, there would be no war, finding it terrifying to leave his sanctuary.\n    </p>\n  </div>\n\n  <!-- NCERT Q4 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #D50000; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #D50000; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q38 (NCERT 4): What explains the attitude of the General in the matter of the enemy soldier? Was it human consideration, lack of national loyalty, dereliction of duty or simply self-absorption?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #D50000; font-weight: bold;\">✓ Answer:</span> General Takima's attitude was driven purely by <b style=\"color: #D50000;\">acute self-absorption</b>. He did not spare the soldier out of humanitarian empathy, nor did he act out of disloyalty to Japan. Suffering from severe cardiovascular illness, the General was completely consumed by his own survival. Knowing that Dr. Sadao was the only surgeon skilled enough to keep him alive, he shielded Sadao from treason and forgot to dispatch his assassins simply because his personal pain eclipsed all military obligations.\n    </p>\n  </div>\n\n</div>\n";

